","import React, { createContext, useContext, useState, useCallback } from "react";

export interface CartItem {
 productSysId: string;
 productName: string;
 productId: string;
 category: string;
 standardCost: string;
 unitOfMeasure: string;
 quantity: number;
 requestedDeliveryDate: string;
 priority: string;
 specialInstructions: string;
 addedAt: number;
}

interface CartContextValue {
 items: CartItem[];
 addItem: (item: CartItem) => void;
 removeItem: (productSysId: string) => void;
 updateItem: (productSysId: string, updates: Partial<CartItem>) => void;
 clearCart: () => void;
 itemCount: number;
}

const CartContext = createContext<CartContextValue | null>(null);

export function CartProvider({ children }: React.PropsWithChildren) {
 const [items, setItems] = useState<CartItem[]>([]);

 const addItem = useCallback((item: CartItem) => {
 setItems((prev) => {
 const idx = prev.findIndex((i) => i.productSysId === item.productSysId);
 if (idx >= 0) {
 const updated = [...prev];
 updated[idx] = { ...item, addedAt: Date.now() };
 return updated;
 }
 return [...prev, { ...item, addedAt: Date.now() }];
 });
 }, []);

 const removeItem = useCallback((productSysId: string) => {
 setItems((prev) => prev.filter((i) => i.productSysId !== productSysId));
 }, []);

 const updateItem = useCallback(
 (productSysId: string, updates: Partial<CartItem>) => {
 setItems((prev) =>
 prev.map((i) =>
 i.productSysId === productSysId ? { ...i, ...updates } : i
 )
 );
 },
 []
 );

 const clearCart = useCallback(() => setItems([]), []);

 return (
 <CartContext.Provider
 value={{
 items,
 addItem,
 removeItem,
 updateItem,
 clearCart,
 itemCount: items.length,
 }}
 >
 {children}
 </CartContext.Provider>
 );
}

export function useCart(): CartContextValue {
 const ctx = useContext(CartContext);
 if (!ctx) throw new Error("useCart must be used within CartProvider");
 return ctx;
}
