 <span className="portal-sidebar__label">{item.label}</span>
 </button>
 );
 })}
 </div>
 </nav>
 );
}
","declare const window: any;

const TABLE = "x_2056099_indust_0_cust_order";
const FIELDS = [
 "sys_id","number","customer","status","priority","order_date",
 "requested_delivery_date","total_order_quantity","order_type",
 "active","delivery_location","special_instructions","customer_reference",
].join(",");

const headers = (): Record<string, string> => ({
 Accept: "application/json",
 "X-UserToken": window.g_ck,
});

export async function fetchOrders(query = "active=true"): Promise<any[]> {
 const params = new URLSearchParams({
 sysparm_display_value: "all",
 sysparm_fields: FIELDS,
 sysparm_query: query,
 });
 const res = await fetch(`/api/now/table/${TABLE}?${params}`, {
 headers: headers(),
 });
 if (!res.ok) throw new Error(`Failed to fetch orders: ${res.status}`);
 const data = await res.json();
 return data.result || [];
}

export interface DashboardKpis {
 activeOrders: number;
 inProduction: number;
 onTimeDeliveryPct: number | null;
 delayedOrders: number;
 completedOrders: number;
 statusBreakdown: Record<string, number>;
}

const val = (field: any): string =>
 typeof field === "string" ? field : field?.value || "";

const disp = (field: any): string =>
 typeof field === "string" ? field : field?.display_value || field?.value || "";

export function computeKpis(orders: any[]): DashboardKpis {
 const now = new Date();
 const terminal = ["completed", "cancelled"];

 const active = orders.filter((o) => !terminal.includes(val(o.status)));
 const inProduction = orders.filter((o) => val(o.status) === "in_production");
 const completed = orders.filter((o) => val(o.status) === "completed");

 let onTimePct: number | null = null;
 if (completed.length > 0) {
 onTimePct = null; // needs actual_completion_date for real calculation
 }

 const delayed = active.filter((o) => {
 const d = val(o.requested_delivery_date);
 return d ? new Date(d) < now : false;
 });

 const statusBreakdown: Record<string, number> = {};
 orders.forEach((o) => {
 const label = disp(o.status) || "Unknown";
 statusBreakdown[label] = (statusBreakdown[label] || 0) + 1;
 });

 return {
 activeOrders: active.length,
 inProduction: inProduction.length,
 onTimeDeliveryPct: onTimePct,
 delayedOrders: delayed.length,
 completedOrders: completed.length,
 statusBreakdown,
 };
}

/* ---- Order Items ---- */

const ITEM_TABLE = "x_2056099_indust_0_cust_ord_item";
const ITEM_FIELDS = [
 "sys_id","number","customer_order","material_product","quantity_ordered",
 "unit_of_measure","requested_delivery_date","priority","item_status",
 "special_instructions","active",
].join(",");

export async function fetchOrderItems(orderSysId: string): Promise<any[]> {
 const params = new URLSearchParams({
 sysparm_display_value: "all",
 sysparm_fields: ITEM_FIELDS,
 sysparm_query: `customer_order=${orderSysId}^ORDERBYnumber`,
 });
 const res = await fetch(`/api/now/table/${ITEM_TABLE}?${params}`, {
 headers: headers(),
 });
 if (!res.ok) throw new Error(`Failed to fetch order items: ${res.status}`);
 const data = await res.json();
 return data.result || [];
}

export async function fetchOrderById(sysId: string): Promise<any> {
 const params = new URLSearchParams({
 sysparm_display_value: "all",
 sysparm_fields: FIELDS,
 });
 const res = await fetch(`/api/now/table/${TABLE}/${sysId}?${params}`, {
 headers: headers(),
 });
 if (!res.ok) throw new Error(`Failed to fetch order: ${res.status}`);
 const data = await res.json();
 return data.result;
}
