","import React, { useMemo } from "react";
import { display, value } from "../../../utils/fields";

interface DelayedOrdersPanelProps {
 orders: any[];
}

export default function DelayedOrdersPanel({ orders }: DelayedOrdersPanelProps) {
 const delayed = useMemo(() => {
 const now = new Date();
 const terminal = ["completed", "cancelled"];
 return orders
 .filter((o) => {
 const s = value(o.status);
 if (terminal.includes(s)) return false;
 const dateStr = value(o.requested_delivery_date);
 if (!dateStr) return false;
 return new Date(dateStr) < now;
 })
 .map((o) => {
 const dateStr = value(o.requested_delivery_date);
 const daysOverdue = Math.floor(
 (Date.now() - new Date(dateStr).getTime()) / 86400000,
 );
 return { ...o, daysOverdue };
 })
 .sort((a: any, b: any) => b.daysOverdue - a.daysOverdue);
 }, [orders]);

 return (
 <div className="dash-panel">
 <h3 className="dash-panel__title">Delayed / Undelivered Orders</h3>
 {delayed.length === 0 ? (
 <div className="dash-panel__good-state">
 <span className="dash-panel__good-icon">✅</span>
 <p className="dash-panel__good-text">
 No delayed orders — all on track!
 </p>
 </div>
 ) : (
 <div className="dash-delayed-list">
 {delayed.map((o: any) => (
 <div key={value(o.sys_id)} className="dash-delayed-row">
 <div className="dash-delayed-main">
