 {display(o.number)}
 </span>
 <span className="dash-delayed-status">
 {display(o.status)}
 </span>
 </div>
 <div className="dash-delayed-meta">
 <span className="dash-delayed-date">
 Due: {display(o.requested_delivery_date)}
 </span>
 <span className="dash-delayed-overdue">
 {o.daysOverdue} day{o.daysOverdue !== 1 ? "s" : ""} overdue
 </span>
 </div>
 </div>
 ))}
 </div>
 )}
 </div>
 );
}
