","import React, { useState, useCallback } from "react";
import { Button } from "@servicenow/react-components/Button";
import { Input } from "@servicenow/react-components/Input";
import { Select } from "@servicenow/react-components/Select";
import { Textarea } from "@servicenow/react-components/Textarea";
import { useCart, CartItem } from "../contexts/CartContext";
import { display, value } from "../utils/fields";

const PRIORITY_OPTIONS = [
 { id: "4", label: "Low" },
 { id: "3", label: "Medium" },
 { id: "2", label: "High" },
 { id: "1", label: "Critical" },
];

interface AddToCartFormProps {
 product: any;
}

export default function AddToCartForm({ product }: AddToCartFormProps) {
 const { addItem, items } = useCart();
 const sysId = value(product.sys_id);
 const existingItem = items.find((i) => i.productSysId === sysId);

 const [quantity, setQuantity] = useState(existingItem?.quantity?.toString() || "1");
 const [deliveryDate, setDeliveryDate] = useState(existingItem?.requestedDeliveryDate || "");
 const [priority, setPriority] = useState(existingItem?.priority || "3");
 const [instructions, setInstructions] = useState(existingItem?.specialInstructions || "");
 const [error, setError] = useState("");
 const [added, setAdded] = useState(false);

 const handleAddToCart = useCallback(() => {
 const qty = parseFloat(quantity);
 if (!quantity || isNaN(qty) || qty <= 0) {
 setError("Quantity must be greater than zero.");
 return;
 }
 setError("");

 const item: CartItem = {
 productSysId: sysId,
 productName: display(product.name),
 productId: display(product.material_product_id),
 category: display(product.category),
 standardCost: display(product.standard_cost),
 unitOfMeasure: display(product.unit_of_measure),
 quantity: qty,
 requestedDeliveryDate: deliveryDate,
 priority,
 specialInstructions: instructions,
 addedAt: Date.now(),
 };
 addItem(item);
 setAdded(true);
 setTimeout(() => setAdded(false), 2500);
 }, [quantity, deliveryDate, priority, instructions, product, sysId, addItem]);

 return (
 <div className="atc-form">
 <h3 className="atc-form__title">Order Configuration</h3>

 <div className="atc-form__fields">
 <div className="atc-form__field">
 <Input
 label="Quantity"
 value={quantity}
 type="number"
 step="1"
 min="1"
 placeholder="Enter quantity"
 onInput={(e: any) => {
 const v = e?.detail?.fieldValue ?? e?.detail?.value ?? "";
 setQuantity(String(v));
 if (error) setError("");
 if (added) setAdded(false);
 }}
 />
 {error && <span className="atc-form__error">{error}</span>}
 </div>

 <div className="atc-form__field">
 <Input
 label="Requested Delivery Date"
 value={deliveryDate}
 type="date"
 placeholder="Select delivery date"
 onInput={(e: any) => {
 const v = e?.detail?.fieldValue ?? e?.detail?.value ?? "";
 setDeliveryDate(String(v));
 if (added) setAdded(false);
 }}
 />
 </div>

 <div className="atc-form__field">
 <Select
 label="Priority"
 items={PRIORITY_OPTIONS}
 selectedItem={priority}
 onSelectedItemSet={(e: any) => {
 const v = e?.detail?.value ?? "3";
 setPriority(String(v));
 if (added) setAdded(false);
 }}
 />
 </div>

 <div className="atc-form__field atc-form__field--full">
 <Textarea
 label="Special Instructions"
 value={instructions}
 placeholder="Enter any special requirements, packaging notes, etc."
 onInput={(e: any) => {
 const v = e?.detail?.fieldValue ?? e?.detail?.value ?? "";
 setInstructions(String(v));
 if (added) setAdded(false);
 }}
 />
 </div>
 </div>

 <div className="atc-form__actions">
 <Button
 label={existingItem ? "Update Cart" : "Add to Cart"}
 variant="primary"
 onClicked={handleAddToCart}
 />
 {added && (
 <span className="atc-form__success">
 ✓ {existingItem ? "Cart updated" : "Added to cart"}
 </span>
 )}
 </div>
 </div>
 );
}
