 <div className="detail__header">
 <Button label="← Back to Catalog" variant="tertiary" onClicked={onBack} />
 <h2 className="detail__title">{display(product.name)}</h2>
 <span className="detail__badge">{display(product.category)}</span>
 </div>
 <div className="detail__grid">
 <DetailRow label="Product ID" val={display(product.material_product_id)} />
 <DetailRow label="Category" val={display(product.category)} />
 <DetailRow label="Material Type" val={display(product.material_type)} />
 <DetailRow label="Standard Cost" val={display(product.standard_cost)} />
 <DetailRow label="Unit of Measure" val={display(product.unit_of_measure)} />
 <DetailRow label="Criticality" val={display(product.criticality)} />
 <DetailRow label="Preferred Supplier" val={display(product.preferred_supplier)} />
 </div>
 {display(product.description) && (
 <div className="detail__description">
 <h3 className="detail__section-title">Description</h3>
 <p className="detail__desc-text">{display(product.description)}</p>
 </div>
 )}
 <AddToCartForm product={product} />
 </div>
 );
}
