export default function CartItemEditor({ item }: CartItemEditorProps) {
 const { updateItem, removeItem } = useCart();
 const [editing, setEditing] = useState(false);
 const [qty, setQty] = useState(item.quantity.toString());
 const [date, setDate] = useState(item.requestedDeliveryDate);
 const [priority, setPriority] = useState(item.priority);
 const [instructions, setInstructions] = useState(item.specialInstructions);
 const [error, setError] = useState("");

 const resetFields = useCallback(() => {
 setQty(item.quantity.toString());
 setDate(item.requestedDeliveryDate);
 setPriority(item.priority);
 setInstructions(item.specialInstructions);
 setError("");
 }, [item]);

 const handleSave = useCallback(() => {
 const parsed = parseFloat(qty);
 if (!qty || isNaN(parsed) || parsed <= 0) {
 setError("Quantity must be greater than zero.");
 return;
 }
 setError("");
 updateItem(item.productSysId, {
 quantity: parsed,
 requestedDeliveryDate: date,
 priority,
 specialInstructions: instructions,
 });
 setEditing(false);
 }, [qty, date, priority, instructions, item.productSysId, updateItem]);

 const handleCancel = useCallback(() => {
 resetFields();
 setEditing(false);
 }, [resetFields]);

 const handleStartEdit = useCallback(() => {
 resetFields();
 setEditing(true);
 }, [resetFields]);

 return (
 <div className="cart-item">
 <div className="cart-item__main">
 <div className="cart-item__info">
 <span className="cart-item__name">{item.productName}</span>
 <span className="cart-item__id">{item.productId}</span>
 </div>
 <span className="cart-item__badge">{item.category}</span>
 </div>

 {editing ? (
 <div className="cart-item__edit-form">
 <div className="cart-item__edit-fields">
 <div className="cart-item__edit-field">
 <Input
 label="Quantity"
 value={qty}
 type="number"
 step="1"
 min="1"
 onInput={(e: any) => {
 const v = e?.detail?.fieldValue ?? e?.detail?.value ?? "";
 setQty(String(v));
 if (error) setError("");
 }}
 />
 {error && <span className="atc-form__error">{error}</span>}
 </div>
 <div className="cart-item__edit-field">
 <Input
 label="Requested Delivery Date"
 value={date}
 type="date"
 onInput={(e: any) => {
 const v = e?.detail?.fieldValue ?? e?.detail?.value ?? "";
 setDate(String(v));
 }}
 />
 </div>
 <div className="cart-item__edit-field">
 <Select
 label="Priority"
 items={PRIORITY_OPTIONS}
 selectedItem={priority}
 onSelectedItemSet={(e: any) => {
 const v = e?.detail?.value ?? "3";
 setPriority(String(v));
 }}
 />
 </div>
 <div className="cart-item__edit-field cart-item__edit-field--full">
 <Textarea
 label="Special Instructions"
 value={instructions}
 placeholder="Any special requirements..."
 onInput={(e: any) => {
 const v = e?.detail?.fieldValue ?? e?.detail?.value ?? "";
 setInstructions(String(v));
 }}
 />
 </div>
 </div>
 <div className="cart-item__edit-actions">
 <Button label="Save" variant="primary" onClicked={handleSave} />
 <Button label="Cancel" variant="secondary" onClicked={handleCancel} />
 </div>
 </div>
 ) : (
 <>
 <div className="cart-item__details">
 <div className="cart-item__detail">
 <span className="cart-item__detail-label">Qty</span>
 <span className="cart-item__detail-value">
 {item.quantity} {item.unitOfMeasure}
 </span>
 </div>
 <div className="cart-item__detail">
 <span className="cart-item__detail-label">Unit Cost</span>
 <span className="cart-item__detail-value">{item.standardCost}</span>
 </div>
 <div className="cart-item__detail">
 <span className="cart-item__detail-label">Priority</span>
 <span className="cart-item__detail-value">
 {PRIORITY_LABELS[item.priority] || item.priority}
 </span>
 </div>
 {item.requestedDeliveryDate && (
 <div className="cart-item__detail">
 <span className="cart-item__detail-label">Delivery</span>
 <span className="cart-item__detail-value">
 {item.requestedDeliveryDate}
 </span>
 </div>
 )}
 </div>
 {item.specialInstructions && (
 <div className="cart-item__instructions">
 <span className="cart-item__detail-label">Instructions</span>
 <span className="cart-item__instructions-text">
 {item.specialInstructions}
 </span>
 </div>
 )}
 <div className="cart-item__actions">
 <Button label="Edit" variant="secondary" onClicked={handleStartEdit} />
 <Button
 label="Remove"
 variant="tertiary"
 onClicked={() => removeItem(item.productSysId)}
 />
 </div>
 </>
 )}
 </div>
 );
}
","import React, { useMemo } from "react";
import { useCart } from "../contexts/CartContext";

export default function OrderSummary() {
 const { items } = useCart();

 const stats = useMemo(() => {
 const totalProducts = items.length;
 const totalQuantity = items.reduce((sum, i) => sum + i.quantity, 0);
 const hasCritical = items.some((i) => i.priority === "1");
 const hasHigh = items.some((i) => i.priority === "2");
 const highestPriority = hasCritical
 ? "Critical"
 : hasHigh
 ? "High"
 : "Standard";
 return { totalProducts, totalQuantity, highestPriority };
 }, [items]);

 if (items.length === 0) return null;

 return (
 <div className="order-summary">
 <h3 className="order-summary__title">Order Summary</h3>
 <div className="order-summary__grid">
 <div className="order-summary__stat">
 <span className="order-summary__stat-value">{stats.totalProducts}</span>
 <span className="order-summary__stat-label">
 Product{stats.totalProducts !== 1 ? "s" : ""}
 </span>
 </div>
 <div className="order-summary__stat">
 <span className="order-summary__stat-value">{stats.totalQuantity}</span>
 <span className="order-summary__stat-label">Total Quantity</span>
 </div>
 <div className="order-summary__stat">
 <span className="order-summary__stat-value">{stats.highestPriority}</span>
 <span className="order-summary__stat-label">Highest Priority</span>
 </div>
 </div>
 <div className="order-summary__items-list">
 {items.map((item) => (
 <div key={item.productSysId} className="order-summary__line">
 <span className="order-summary__line-name">{item.productName}</span>
 <span className="order-summary__line-qty">
 × {item.quantity} {item.unitOfMeasure}
 </span>
 </div>
 ))}
 </div>
 </div>
 );
}
","import React, { useState, useCallback } from "react";
import { Button } from "@servicenow/react-components/Button";
import { useCart } from "../contexts/CartContext";
import CartItemEditor from "./CartItemEditor";
import OrderSummary from "./OrderSummary";

interface CartViewProps {
 onBack: () => void;
 onViewProduct: (sysId: string) => void;
}

export default function CartView({ onBack, onViewProduct }: CartViewProps) {
 const { items, clearCart, itemCount } = useCart();
 const [submitted, setSubmitted] = useState(false);

 const handleReviewSubmit = useCallback(() => {
 setSubmitted(true);
 setTimeout(() => setSubmitted(false), 4000);
 }, []);

 const isEmpty = itemCount === 0;

 return (
 <div className="cart-view">
 <div className="cart-view__header">
 <Button label="← Back to Catalog" variant="tertiary" onClicked={onBack} />
 <div className="cart-view__title-row">
 <h2 className="cart-view__title">Order Review</h2>
 {!isEmpty && (
 <span className="cart-view__count">
 {itemCount} item{itemCount !== 1 ? "s" : ""}
 </span>
 )}
 </div>
 {!isEmpty && (
 <p className="cart-view__subtitle">
 Review your selections below. Edit any item inline, then proceed
 when ready.
 </p>
 )}
 </div>

 {isEmpty ? (
 <div className="catalog-state">
 <p className="catalog-state__icon">🛒</p>
 <p className="catalog-state__text">Your cart is empty</p>
 <p className="catalog-state__hint">
 Browse the catalog and add products to get started
 </p>
 <div className="catalog-state__action">
 <Button
 label="Browse Catalog"
 variant="primary"
 onClicked={onBack}
 />
 </div>
 </div>
 ) : (
 <>
 <div className="cart-view__items">
 {items.map((item) => (
 <CartItemEditor key={item.productSysId} item={item} />
 ))}
 </div>

 <OrderSummary />

 <div className="cart-view__review-footer">
 <div className="cart-view__review-left">
 <Button
 label="Clear Cart"
 variant="tertiary"
 onClicked={clearCart}
 />
 <Button
 label="Continue Shopping"
 variant="secondary"
 onClicked={onBack}
 />
 </div>
 <div className="cart-view__review-right">
 <Button
 label="Review & Submit Order"
 variant="primary"
 disabled={isEmpty}
 onClicked={handleReviewSubmit}
 />
 </div>
 </div>

 {submitted && (
 <div className="cart-view__submit-notice">
 <p className="cart-view__submit-notice-text">
 ✓ Order reviewed successfully. Submission will be available in a
 future update.
 </p>
 </div>
 )}
 </>
 )}
 </div>
 );
}
","import React, { useState, useEffect, useMemo } from "react";
import { Input } from "@servicenow/react-components/Input";
import { fetchProducts } from "../../services/productService";
import { value } from "../../utils/fields";
import StorefrontCard from "../StorefrontCard";
import ProductDetail from "../ProductDetail";
import CartView from "../CartView";

declare const window: any;

const CATEGORIES = [
 { id: "", label: "All" },
 { id: "component", label: "Component" },
 { id: "consumable", label: "Consumable" },
 { id: "maintenance_spare", label: "Maintenance Spare" },
 { id: "finished_product", label: "Finished Product" },
];

interface CatalogSectionProps {
 catalogView: string;
 recordId: string | null;
 onNavigate: (view: string, id?: string | null) => void;
}

export default function CatalogSection({ catalogView, recordId, onNavigate }: CatalogSectionProps) {
 const [products, setProducts] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [searchTerm, setSearchTerm] = useState("");
 const [category, setCategory] = useState("");

 useEffect(() => {
 setLoading(true);
 fetchProducts("active=true")
 .then(setProducts)
 .catch(() => setProducts([]))
 .finally(() => setLoading(false));
 }, []);

 const filtered = useMemo(() => {
 const term = searchTerm.toLowerCase();
 return products.filter((p) => {
 const name = (p.name?.display_value || p.name || "").toLowerCase();
 const desc = (p.description?.display_value || p.description || "").toLowerCase();
 const pid = (p.material_product_id?.display_value || p.material_product_id || "").toLowerCase();
 const cat = value(p.category);
 const matchesSearch = !term || name.includes(term) || desc.includes(term) || pid.includes(term);
 const matchesCat = !category || cat === category;
 return matchesSearch && matchesCat;
 });
 }, [products, searchTerm, category]);

 if (catalogView === "cart") {
 return (
 <CartView
 onBack={() => onNavigate("list")}
 onViewProduct={(id) => onNavigate("detail", id)}
 />
 );
 }

 if (catalogView === "detail" && recordId) {
 return (
 <ProductDetail
 productId={recordId}
 onBack={() => onNavigate("list")}
 />
 );
 }

 return (
 <div>
 <div className="storefront-hero">
 <h2 className="storefront-hero__title">Browse Our Product Catalog</h2>
 <p className="storefront-hero__subtitle">
 Find industrial materials, components, and supplies for your operations
 </p>
 <div className="storefront-hero__search">
 <Input
 value={searchTerm}
 placeholder="Search products by name, description, or ID..."
 type="text"
 onInput={(e: any) => {
 const v = e?.detail?.fieldValue ?? e?.detail?.value ?? "";
 setSearchTerm(v);
 }}
 />
 </div>
 <p className="storefront-hero__count">
 {filtered.length} product{filtered.length !== 1 ? "s" : ""} available
 </p>
 </div>

 <div className="category-pills">
 {CATEGORIES.map((c) => (
 <button
 key={c.id}
 className={`category-pill${category === c.id ? " category-pill--active" : ""}`}
 onClick={() => setCategory(c.id)}
 >
 {c.label}
 </button>
 ))}
 </div>

 {loading ? (
 <div className="catalog-state">
 <div className="catalog-spinner" />
 <p className="catalog-state__text">Loading products...</p>
 </div>
 ) : filtered.length === 0 ? (
 <div className="catalog-state">
 <p className="catalog-state__icon">🔍</p>
 <p className="catalog-state__text">No products found</p>
 <p className="catalog-state__hint">Try adjusting your search or filters</p>
 </div>
 ) : (
 <div className="storefront-grid">
 {filtered.map((p) => (
 <StorefrontCard
 key={value(p.sys_id)}
 product={p}
 onViewDetails={(id) => onNavigate("detail", id)}
 />
 ))}
 </div>
 )}
 </div>
 );
}
","import React from "react";

const STATUS_VARIANT: Record<string, string> = {
 Draft: "muted",
 Submitted: "info",
 "Under Validation": "warning",
 Approved: "primary",
 Rejected: "critical",
 "In Production": "info",
 "Partially Completed": "warning",
 Completed: "positive",
 Cancelled: "muted",
 Pending: "warning",
 Validated: "info",
 "Material Check": "warning",
};

interface StatusBadgeProps {
 status: string;
}

export default function StatusBadge({ status }: StatusBadgeProps) {
 const variant = STATUS_VARIANT[status] || "muted";
 return (
 <span className={`status-badge status-badge--${variant}`}>{status}</span>
 );
}
","import React, { useState, useMemo } from "react";
import { Input } from "@servicenow/react-components/Input";
import { Button } from "@servicenow/react-components/Button";
import StatusBadge from "./StatusBadge";
import { display, value } from "../../../utils/fields";

interface OrderListViewProps {
 orders: any[];
 loading: boolean;
 onViewOrder: (sysId: string) => void;
}

const STATUS_FILTERS = [
 { label: "All", val: "" },
 { label: "Submitted", val: "submitted" },
 { label: "Approved", val: "approved" },
 { label: "In Production", val: "in_production" },
 { label: "Completed", val: "completed" },
 { label: "Cancelled", val: "cancelled" },
];

export default function OrderListView({ orders, loading, onViewOrder }: OrderListViewProps) {
 const [search, setSearch] = useState("");
 const [statusFilter, setStatusFilter] = useState("");
 const [newestFirst, setNewestFirst] = useState(true);

 const filtered = useMemo(() => {
 let list = orders;
 if (search) {
 const term = search.toLowerCase();
 list = list.filter(
 (o) =>
 display(o.number).toLowerCase().includes(term) ||
 display(o.customer_reference).toLowerCase().includes(term)
 );
 }
 if (statusFilter) {
 list = list.filter((o) => value(o.status) === statusFilter);
 }
 list = [...list].sort((a, b) => {
 const da = value(a.order_date) || "";
 const db = value(b.order_date) || "";
 return newestFirst ? db.localeCompare(da) : da.localeCompare(db);
 });
 return list;
 }, [orders, search, statusFilter, newestFirst]);

 if (loading) {
 return (
 <div className="orders-section">
 <p style={{ textAlign: "center", padding: "3rem 0", color: "var(--snx-color-text-muted)" }}>
 Loading orders…
 </p>
 </div>
 );
 }

 return (
 <div className="orders-section">
 <div className="orders-header">
 <h2 className="orders-header__title">
 My Orders{" "}
 <span className="orders-header__count">({filtered.length})</span>
 </h2>
 </div>

 <div className="orders-toolbar">
 <div className="orders-toolbar__search">
 <Input
 placeholder="Search by order # or reference…"
 type="search"
 value={search}
 onInput={(e: any) => setSearch(e.detail?.fieldValue ?? e.detail?.value ?? "")}
 />
 </div>
 <div className="orders-toolbar__sort">
 <Button
 label={newestFirst ? "↓ Newest first" : "↑ Oldest first"}
 variant="secondary"
 onClicked={() => setNewestFirst((p) => !p)}
 />
 </div>
 </div>

 <div className="orders-status-pills">
 {STATUS_FILTERS.map((f) => (
 <button
 key={f.val}
 className={`category-pill${statusFilter === f.val ? " category-pill--active" : ""}`}
 onClick={() => setStatusFilter(f.val)}
 >
 {f.label}
 </button>
 ))}
 </div>

 {filtered.length === 0 ? (
 <div className="placeholder-section" style={{ minHeight: 200 }}>
 <p className="placeholder-section__icon">📋</p>
 <p className="placeholder-section__desc">No orders found.</p>
 </div>
 ) : (
 <>
 <div className="orders-list-header">
 <span>Order #</span>
 <span>Details</span>
 <span>Status</span>
 <span style={{ textAlign: "right" }}>Qty</span>
 <span />
 </div>
 <div className="orders-list">
 {filtered.map((o) => (
 <div className="order-row" key={value(o.sys_id)}>
 <span className="order-row__number">{display(o.number)}</span>
 <div className="order-row__meta">
 <span className="order-row__meta-primary">
 {display(o.order_type)} &middot; {display(o.priority)}
 </span>
 <span className="order-row__meta-secondary">
 Ordered {display(o.order_date)}
 {display(o.customer_reference) ? ` · Ref: ${display(o.customer_reference)}` : ""}
 </span>
 </div>
 <StatusBadge status={display(o.status)} />
 <span className="order-row__qty">{display(o.total_order_quantity)}</span>
 <Button
 label="View Order"
 variant="secondary"
 onClicked={() => onViewOrder(value(o.sys_id))}
 />
 </div>
 ))}
 </div>
 </>
 )}
 </div>
 );
}
