","import React from "react";
import { value } from "../../../utils/fields";

interface DeliveryKpisProps {
 orders: any[];
}

export default function DeliveryKpis({ orders }: DeliveryKpisProps) {
 const now = new Date();
 const terminal = ["completed", "cancelled"];
 const active = orders.filter(o => !terminal.includes(value(o.status)));
 const completed = orders.filter(o => value(o.status) === "completed");

 const dueThisWeek = active.filter(o => {
 const d = value(o.requested_delivery_date);
 if (!d) return false;
 const days = Math.ceil((new Date(d).getTime() - now.getTime()) / 86400000);
 return days >= 0 && days <= 7;
 });

 const delayed = active.filter(o => {
 const d = value(o.requested_delivery_date);
 return d ? new Date(d) < now : false;
 });

 return (
 <div className="del-kpi-row">
 <div className="del-kpi-card del-kpi-card--primary">
 <span className="del-kpi-card__icon">📦</span>
 <span className="del-kpi-card__value">{active.length}</span>
 <span className="del-kpi-card__label">Active Orders</span>
 </div>
 <div className="del-kpi-card del-kpi-card--warning">
 <span className="del-kpi-card__icon">📅</span>
 <span className="del-kpi-card__value">{dueThisWeek.length}</span>
 <span className="del-kpi-card__label">Due This Week</span>
