","import React from "react";
import { value } from "../../../utils/fields";

interface DeliveryStatusTagProps {
 order: any;
}

export function getDeliveryCondition(order: any): { label: string; variant: string } {
 const status = value(order.status);
 if (status === "completed") return { label: "Completed", variant: "muted" };
 if (status === "cancelled") return { label: "Cancelled", variant: "muted" };

 const dateStr = value(order.requested_delivery_date);
 if (!dateStr) return { label: "No Date", variant: "muted" };

 const now = new Date();
 const deliveryDate = new Date(dateStr);
 const daysUntil = Math.ceil((deliveryDate.getTime() - now.getTime()) / 86400000);

 if (daysUntil < 0) return { label: "Delayed", variant: "critical" };
 if (daysUntil <= 7) return { label: "Due Soon", variant: "warning" };
 return { label: "On Track", variant: "positive" };
}

export default function DeliveryStatusTag({ order }: DeliveryStatusTagProps) {
 const { label, variant } = getDeliveryCondition(order);
 return (
 <span className={`delivery-tag delivery-tag--${variant}`}>{label}</span>
 );
}
