","declare const window: any;

const STOCK_TABLE = "x_2056099_indust_0_inv_stock";
const STOCK_FIELDS = [
 "sys_id","material_product","total_quantity","available_quantity",
 "reserved_quantity","reorder_level","safety_stock","status","active",
].join(",");

const headers = (): Record<string, string> => ({
 Accept: "application/json",
 "X-UserToken": window.g_ck,
});

export interface ProductAvailability {
 productSysId: string;
 productName: string;
 productId: string;
 category: string;
 unitOfMeasure: string;
 availableQty: number;
 totalQty: number;
 reorderLevel: number;
 safetyStock: number;
 availabilityState: "available" | "limited" | "unavailable";
 availabilityLabel: string;
}

export async function fetchInventoryStock(): Promise<any[]> {
 const params = new URLSearchParams({
 sysparm_display_value: "all",
 sysparm_fields: STOCK_FIELDS,
 sysparm_query: "active=true^ORDERBYmaterial_product",
 });
 const res = await fetch(`/api/now/table/${STOCK_TABLE}?${params}`, {
 headers: headers(),
 });
 if (!res.ok) throw new Error(`Failed to fetch stock: ${res.status}`);
 const data = await res.json();
 return data.result || [];
}

function numVal(field: any): number {
 const raw = typeof field === "string" ? field : (field?.value || "0");
 return parseFloat(raw) || 0;
}

function strVal(field: any): string {
 return typeof field === "string" ? field : (field?.value || "");
}

function strDisp(field: any): string {
 return typeof field === "string" ? field : (field?.display_value || "");
}

export function computeAvailability(
 stockRecords: any[],
 products: any[]
): ProductAvailability[] {
 const stockMap = new Map<string, {
 available: number; total: number; reorder: number; safety: number;
 }>();

 stockRecords.forEach((s) => {
 const pid = strVal(s.material_product);
 if (!pid) return;
 const cur = stockMap.get(pid) || { available: 0, total: 0, reorder: 0, safety: 0 };
 cur.available += numVal(s.available_quantity);
 cur.total += numVal(s.total_quantity);
 cur.reorder = Math.max(cur.reorder, numVal(s.reorder_level));
 cur.safety = Math.max(cur.safety, numVal(s.safety_stock));
 stockMap.set(pid, cur);
 });

 return products
 .filter((p) => {
 const a = strVal(p.active);
 return a === "true" || a === "1";
 })
 .map((p) => {
 const pId = strVal(p.sys_id);
 const stock = stockMap.get(pId);
 const availableQty = stock?.available || 0;
 const totalQty = stock?.total || 0;
 const reorderLevel = stock?.reorder || 0;
 const safetyStock = stock?.safety || 0;

 let state: "available" | "limited" | "unavailable";
 let label: string;

 if (availableQty <= 0) {
 state = "unavailable";
 label = "Currently Unavailable";
 } else if (availableQty <= reorderLevel || availableQty <= safetyStock) {
 state = "limited";
 label = "Limited Availability";
 } else {
 state = "available";
 label = "Available";
 }

 return {
 productSysId: pId,
 productName: strDisp(p.name),
 productId: strDisp(p.material_product_id),
 category: strDisp(p.category),
 unitOfMeasure: strDisp(p.unit_of_measure),
 availableQty,
 totalQty,
 reorderLevel,
 safetyStock,
 availabilityState: state,
 availabilityLabel: label,
 };
 });
}
