 </div>
 <ActiveBadge isActive={active} />
 </div>

 <div className="profile-cards">
 <div className="profile-card">
 <h3 className="profile-card__title">🏢 Company Information</h3>
 <div className="profile-card__fields">
 <Field label="Customer Name" val={display(customer.customer_name)} />
 <Field label="Customer ID" val={display(customer.customer_id)} />
 <Field label="Customer Type" val={display(customer.customer_type)} />
 <Field label="Industry" val={display(customer.industry)} />
 </div>
 </div>

 <div className="profile-card">
 <h3 className="profile-card__title">📧 Contact Information</h3>
 <div className="profile-card__fields">
 <Field label="Primary Email" val={display(customer.primary_contact_email)} />
 <Field label="Primary Phone" val={display(customer.primary_contact_phone)} />
 </div>
 </div>

 <div className="profile-card">
 <h3 className="profile-card__title">💳 Account Information</h3>
 <div className="profile-card__fields">
 <Field label="Payment Terms" val={display(customer.payment_terms)} />
 <Field label="Credit Limit" val={display(customer.credit_limit)} />
 <Field label="Account Status" val={active ? "Active" : "Inactive"} />
 </div>
 </div>

 {display(customer.notes) && (
 <div className="profile-card profile-card--full">
 <h3 className="profile-card__title">📝 Notes</h3>
 <p className="profile-card__notes">{display(customer.notes)}</p>
 </div>
 )}
 </div>
 </div>
 );
}
","import React, { useState, useEffect, useCallback } from "react";
import PortalHeader from "./components/portal/PortalHeader";
import PortalSidebar from "./components/portal/PortalSidebar";
import DashboardSection from "./components/portal/DashboardSection";
import CatalogSection from "./components/portal/CatalogSection";
import MyOrdersSection from "./components/portal/MyOrdersSection";
import DeliverySection from "./components/portal/DeliverySection";
import DemandSection from "./components/portal/DemandSection";
import SurveysSection from "./components/portal/SurveysSection";
import ProfileSection from "./components/portal/ProfileSection";

declare const window: any;

interface PortalState {
 section: string;
 view: string;
 recordId: string | null;
}

function getStateFromUrl(): PortalState {
 const params = new URLSearchParams(window.location.search);
 return {
 section: params.get("section") || "dashboard",
 view: params.get("view") || "list",
 recordId: params.get("id") || null,
 };
}

export default function App() {
 const [state, setState] = useState<PortalState>(getStateFromUrl);

 useEffect(() => {
 const onPopState = () => setState(getStateFromUrl());
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const pushUrl = useCallback((next: PortalState) => {
 const params = new URLSearchParams({ section: next.section });
 if ((next.section === "catalog" || next.section === "orders") && next.view !== "list") params.set("view", next.view);
 if (next.recordId) params.set("id", next.recordId);
 const path = `${window.location.pathname}?${params}`;
 window.history.pushState(next, "", path);
 setState(next);
 }, []);

 const navigateSection = useCallback(
 (section: string) => pushUrl({ section, view: "list", recordId: null }),
 [pushUrl]
 );

 const navigateCatalog = useCallback(
 (view: string, id?: string | null) =>
 pushUrl({ section: "catalog", view, recordId: id || null }),
 [pushUrl]
 );

 const navigateCart = useCallback(
 () => pushUrl({ section: "catalog", view: "cart", recordId: null }),
 [pushUrl]
 );

 const navigateOrders = useCallback(
 (view: string, id?: string | null) =>
 pushUrl({ section: "orders", view, recordId: id || null }),
 [pushUrl]
 );

 const renderSection = () => {
 switch (state.section) {
 case "catalog":
 return (
 <CatalogSection
 catalogView={state.view}
 recordId={state.recordId}
 onNavigate={navigateCatalog}
 />
 );
 case "orders":
 return (
 <MyOrdersSection
 ordersView={state.view}
 recordId={state.recordId}
 onNavigate={navigateOrders}
 />
 );
 case "delivery":
 return (
 <DeliverySection
 onViewOrder={(id) => pushUrl({ section: "orders", view: "detail", recordId: id })}
 />
 );
 case "demand":
 return <DemandSection />;
 case "surveys":
 return <SurveysSection />;
 case "profile":
 return <ProfileSection />;
 default:
 return <DashboardSection />;
 }
 };

 return (
 <div className="portal-shell">
 <PortalHeader onViewCart={navigateCart} />
 <div className="portal-body">
 <PortalSidebar activeSection={state.section} onNavigate={navigateSection} />
 <main className="portal-content">{renderSection()}</main>
 </div>
 </div>
 );
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","/* ========================================
 Product Catalog – Horizon Design System
 ======================================== */

:root {
 --snx-color-surface: rgb(var(--now-color_background--primary, 255, 255, 255));
 --snx-color-surface-alt: rgb(var(--now-color_background--secondary, 245, 246, 247));
 --snx-color-border: rgb(var(--now-container-card--border-color, 207, 213, 215));
 --snx-color-text: rgb(var(--now-color_text--primary, 16, 23, 26));
 --snx-color-text-muted: rgb(var(--now-color_text--secondary, 75, 85, 89));
 --snx-color-primary: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 --snx-color-on-primary: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 --snx-color-focus: rgb(var(--now-color_focus-ring, 53, 147, 37));
 --snx-space-xs: var(--now-static-space--xs, 0.25rem);
 --snx-space-sm: var(--now-static-space--sm, 0.5rem);
 --snx-space-md: var(--now-static-space--md, 0.75rem);
 --snx-space-lg: var(--now-static-space--lg, 1rem);
 --snx-space-xl: var(--now-static-space--xl, 1.5rem);
 --snx-space-xxl: var(--now-static-space--xxl, 2rem);
 --snx-radius-card: var(--now-container-card--border-radius, 8px);
 --snx-font: var(--now-font-family, "Lato", Arial, sans-serif);
}

/* ---- Page Layout ---- */
.catalog-page {
 max-width: 1280px;
 margin: 0 auto;
 padding: var(--snx-space-xl);
 font-family: var(--snx-font);
 color: var(--snx-color-text);
 background-color: var(--snx-color-surface);
 min-height: 100vh;
}

/* ---- Header ---- */
.catalog-header {
 margin-bottom: var(--snx-space-xl);
}

.catalog-header__title-row {
 display: flex;
 align-items: baseline;
 justify-content: space-between;
 margin: 0 0 var(--snx-space-lg) 0;
}

.catalog-header__title {
 margin: 0;
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.catalog-header__count {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
}

.catalog-header__search {
 max-width: 480px;
}

/* ---- Filters ---- */
.catalog-filters {
 display: flex;
 gap: var(--snx-space-lg);
 margin-bottom: var(--snx-space-xl);
 flex-wrap: wrap;
}

.catalog-filters__group {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-xs);
 min-width: 200px;
}

.catalog-filters__label {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 font-weight: 600;
 color: var(--snx-color-text-muted);
}

/* ---- Product Grid ---- */
.product-grid {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
 gap: var(--snx-space-xl);
}

/* ---- Product Card ---- */
.product-card {
 display: flex;
 flex-direction: column;
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 box-shadow: var(--now-static-drop-shadow--sm);
 overflow: hidden;
 transition: box-shadow 150ms ease, transform 150ms ease;
}

.product-card:hover {
 box-shadow: var(--now-static-drop-shadow--md);
 transform: translateY(-2px);
}

.product-card__header {
 padding: var(--snx-space-lg);
 border-bottom: 1px solid var(--snx-color-border);
 background-color: var(--snx-color-surface-alt);
}

.product-card__title-row {
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: var(--snx-space-sm);
 margin-bottom: var(--snx-space-xs);
}

.product-card__name {
 font-weight: 600;
 font-size: var(--now-static-font-size--md, 1rem);
 color: var(--snx-color-text);
 white-space: nowrap;
 overflow: hidden;
 text-overflow: ellipsis;
}

.product-card__badge {
 display: inline-block;
 padding: 2px var(--snx-space-sm);
 font-size: 0.6875rem;
 font-weight: 600;
 color: var(--snx-color-on-primary);
 background-color: var(--snx-color-primary);
 border-radius: var(--now-static-border-radius--lg, 0.5rem);
 white-space: nowrap;
 text-transform: capitalize;
}

.product-card__id {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
}

.product-card__body {
 padding: var(--snx-space-lg);
 flex: 1;
}

.product-card__desc {
 margin: 0 0 var(--snx-space-md) 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
 line-height: var(--now-static-line-height, 1.25);
}

.product-card__meta {
 display: flex;
 gap: var(--snx-space-xl);
}

.product-card__meta-label {
 display: block;
 font-size: 0.6875rem;
 color: var(--snx-color-text-muted);
 text-transform: uppercase;
 letter-spacing: 0.04em;
 margin-bottom: 2px;
}

.product-card__meta-value {
 display: block;
