 font-weight: 600;
 color: var(--snx-color-text);
}

.product-card__footer {
 padding: var(--snx-space-md) var(--snx-space-lg);
 border-top: 1px solid var(--snx-color-border);
 display: flex;
 justify-content: flex-end;
}

/* ---- Loading / Empty States ---- */
.catalog-state {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: var(--snx-space-xxl) 0;
 min-height: 300px;
 text-align: center;
}

.catalog-state__icon {
 font-size: 3rem;
 margin: 0 0 var(--snx-space-lg) 0;
}

.catalog-state__text {
 margin: 0 0 var(--snx-space-sm) 0;
