@keyframes spin {
 100% { transform: rotate(360deg); }
}

/* ---- Detail View ---- */
.detail {
 max-width: 800px;
 margin: 0 auto;
}

.detail__header {
 margin-bottom: var(--snx-space-xl);
}

.detail__title {
