}

/* ---- Responsive ---- */
@media (max-width: 768px) {
 .product-grid {
 grid-template-columns: 1fr;
 }
 .detail__grid {
 grid-template-columns: 1fr;
 }
 .catalog-filters {
 flex-direction: column;
 }
 .atc-form__fields {
 grid-template-columns: 1fr;
 }
 .cart-item__details {
 flex-direction: column;
 gap: var(--snx-space-md);
 }
 .cart-item__edit-fields {
 grid-template-columns: 1fr;
 }
 .catalog-header__title-row {
 flex-direction: column;
 gap: var(--snx-space-md);
 }
 .catalog-header__right {
 align-self: flex-end;
 }
 .order-summary__grid {
 flex-direction: column;
 gap: var(--snx-space-lg);
 }
 .cart-view__review-footer {
 flex-direction: column;
 gap: var(--snx-space-md);
 align-items: stretch;
 }
 .cart-view__review-left {
 justify-content: center;
 }
 .cart-view__review-right {
 justify-content: center;
 }
}
","/* ========================================
 Customer Portal – Shell & Marketplace
 ======================================== */

/* ---- Portal Shell Layout ---- */
.portal-shell {
 display: flex;
 flex-direction: column;
 min-height: 100vh;
 font-family: var(--snx-font);
 color: var(--snx-color-text);
 background-color: var(--snx-color-surface);
}

.portal-body {
 display: flex;
 flex: 1;
 overflow: hidden;
}

.portal-content {
 flex: 1;
 overflow-y: auto;
 padding: var(--snx-space-xl);
 background-color: var(--snx-color-surface);
}

/* ---- Portal Header ---- */
.portal-header {
 display: flex;
 align-items: center;
 justify-content: space-between;
 padding: 0 var(--snx-space-xl);
 height: 56px;
 background: linear-gradient(
 135deg,
 rgb(var(--now-color_brand--primary, 0, 100, 140)),
 rgb(var(--now-color_brand--secondary, 0, 128, 163))
 );
 color: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 box-shadow: var(--now-static-drop-shadow--md);
 position: relative;
 z-index: 10;
}

.portal-header__brand {
 display: flex;
 align-items: baseline;
 gap: var(--snx-space-md);
}

.portal-header__name {
 margin: 0;
 font-size: var(--now-static-font-size--lg, 1.25rem);
 font-weight: 700;
 letter-spacing: -0.01em;
}

.portal-header__tagline {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 opacity: 0.85;
 font-weight: 400;
}

.portal-header__actions {
 display: flex;
 align-items: center;
 gap: var(--snx-space-md);
}

/* ---- Sidebar Navigation ---- */
.portal-sidebar {
 width: 220px;
 min-width: 220px;
 background-color: rgb(var(--now-color_background--secondary, 245, 246, 247));
 border-right: 1px solid var(--snx-color-border);
 overflow-y: auto;
 display: flex;
 flex-direction: column;
 padding: var(--snx-space-md) 0;
}

.portal-sidebar__nav {
 display: flex;
 flex-direction: column;
 gap: 2px;
 padding: 0 var(--snx-space-sm);
 list-style: none;
 margin: 0;
}

.portal-sidebar__item {
 display: flex;
 align-items: center;
 gap: var(--snx-space-md);
 padding: 10px var(--snx-space-md);
 border-radius: 6px;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 font-weight: 500;
 color: var(--snx-color-text);
 cursor: pointer;
 transition: background-color 120ms ease, color 120ms ease;
 border: none;
 background: none;
 width: 100%;
 text-align: left;
 font-family: inherit;
}

.portal-sidebar__item:hover {
 background-color: rgba(var(--now-color_background--secondary, 245, 246, 247), 0.7);
}

.portal-sidebar__item--active {
 background-color: rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.12);
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 font-weight: 600;
}

.portal-sidebar__icon {
 font-size: 1.1rem;
 width: 24px;
 text-align: center;
 flex-shrink: 0;
}

.portal-sidebar__label {
 white-space: nowrap;
 overflow: hidden;
 text-overflow: ellipsis;
}

/* ---- Storefront Hero Banner ---- */
.storefront-hero {
 background: linear-gradient(
 135deg,
 rgb(var(--now-color_brand--primary, 0, 100, 140)),
 rgb(var(--now-color_brand--secondary, 0, 128, 163))
 );
 border-radius: var(--snx-radius-card);
 padding: var(--snx-space-xxl) var(--snx-space-xl);
 margin-bottom: var(--snx-space-xl);
 text-align: center;
 color: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
}

.storefront-hero__title {
 margin: 0 0 var(--snx-space-xs) 0;
 font-size: 1.75rem;
 font-weight: 700;
 letter-spacing: -0.02em;
}

.storefront-hero__subtitle {
 margin: 0 0 var(--snx-space-lg) 0;
 font-size: var(--now-static-font-size--md, 1rem);
 opacity: 0.9;
}

.storefront-hero__search {
 max-width: 560px;
 margin: 0 auto;
}

.storefront-hero__count {
 margin: var(--snx-space-md) 0 0 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 opacity: 0.8;
}

/* ---- Category Pills ---- */
.category-pills {
 display: flex;
 flex-wrap: wrap;
 gap: var(--snx-space-sm);
 margin-bottom: var(--snx-space-xl);
 padding: 0 var(--snx-space-xs);
}

.category-pill {
 display: inline-flex;
 align-items: center;
 padding: 6px 16px;
 border-radius: 20px;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 font-weight: 600;
 cursor: pointer;
 transition: all 120ms ease;
 border: 1px solid var(--snx-color-border);
 background-color: var(--snx-color-surface);
 color: var(--snx-color-text);
 font-family: inherit;
}

.category-pill:hover {
 border-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}

.category-pill--active {
 background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 color: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
 border-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}

.category-pill--active:hover {
 color: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
}

/* ---- Storefront Product Grid ---- */
.storefront-grid {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
 gap: var(--snx-space-xl);
}

/* ---- Storefront Card ---- */
.storefront-card {
 display: flex;
 flex-direction: column;
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 box-shadow: var(--now-static-drop-shadow--sm);
 overflow: hidden;
 transition: box-shadow 180ms ease, transform 180ms ease;
}

.storefront-card:hover {
 box-shadow: var(--now-static-drop-shadow--lg);
 transform: translateY(-3px);
}

.storefront-card__badges {
 display: flex;
 gap: var(--snx-space-sm);
 flex-wrap: wrap;
 padding: var(--snx-space-md) var(--snx-space-lg) 0;
}

.storefront-card__badge {
 display: inline-block;
 padding: 3px 10px;
 font-size: 0.6875rem;
 font-weight: 600;
 border-radius: 12px;
 text-transform: capitalize;
 white-space: nowrap;
}

.storefront-card__badge--category {
 background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 color: rgb(var(--now-actionable_label--primary--color, 255, 255, 255));
}

.storefront-card__badge--type {
 background-color: rgba(var(--now-color_text--secondary, 75, 85, 89), 0.15);
 color: var(--snx-color-text);
}

.storefront-card__body {
 padding: var(--snx-space-md) var(--snx-space-lg) var(--snx-space-lg);
 flex: 1;
 display: flex;
 flex-direction: column;
}

.storefront-card__name {
 margin: 0 0 2px 0;
 font-size: var(--now-static-font-size--lg, 1.125rem);
 font-weight: 700;
 color: var(--snx-color-text);
 line-height: 1.3;
}

.storefront-card__pid {
 margin: 0 0 var(--snx-space-sm) 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
}

.storefront-card__desc {
 margin: 0 0 var(--snx-space-md) 0;
 font-size: var(--now-static-font-size--sm, 0.8125rem);
 color: var(--snx-color-text-muted);
 line-height: 1.45;
 flex: 1;
}

.storefront-card__price-row {
 display: flex;
 align-items: baseline;
 justify-content: space-between;
 margin-bottom: var(--snx-space-md);
 padding-top: var(--snx-space-md);
 border-top: 1px solid var(--snx-color-border);
}

.storefront-card__price {
 font-size: 1.35rem;
 font-weight: 700;
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}

.storefront-card__unit {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
 font-weight: 500;
}

.storefront-card__actions {
 display: flex;
 gap: var(--snx-space-sm);
 padding-top: var(--snx-space-sm);
}

.storefront-card__actions > * {
 flex: 1;
}

.storefront-card__added-msg {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: rgb(var(--now-color_alert--positive-2, 32, 135, 46));
 font-weight: 600;
 text-align: center;
 padding: var(--snx-space-xs) 0;
 animation: fadeIn 200ms ease;
}

/* ---- Placeholder Sections ---- */
.placeholder-section {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 min-height: 400px;
 text-align: center;
 padding: var(--snx-space-xxl);
}

.placeholder-section__icon {
 font-size: 4rem;
 margin: 0 0 var(--snx-space-lg) 0;
 opacity: 0.7;
}

.placeholder-section__title {
 margin: 0 0 var(--snx-space-sm) 0;
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.placeholder-section__coming {
 margin: 0 0 var(--snx-space-md) 0;
 font-size: var(--now-static-font-size--md, 1rem);
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 font-weight: 600;
}

.placeholder-section__desc {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text-muted);
 max-width: 420px;
 line-height: 1.5;
}

/* ---- Marketplace Filters Row ---- */
.storefront-filters {
 display: flex;
 gap: var(--snx-space-lg);
 margin-bottom: var(--snx-space-lg);
 align-items: flex-end;
 flex-wrap: wrap;
}

.storefront-filters__group {
 min-width: 200px;
}

/* ---- Customer Dashboard ---- */
.cust-dashboard {
 max-width: 1100px;
}

.cust-dashboard__welcome {
 margin-bottom: var(--snx-space-xl);
}

.cust-dashboard__title {
 margin: 0 0 var(--snx-space-xs) 0;
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.cust-dashboard__subtitle {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text-muted);
}

/* ---- Dashboard KPI Cards ---- */
.dash-kpi-row {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: var(--snx-space-lg);
 margin-bottom: var(--snx-space-xl);
}

.dash-kpi-card {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: var(--snx-space-xl) var(--snx-space-lg);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 box-shadow: var(--now-static-drop-shadow--sm);
 text-align: center;
 transition: box-shadow 150ms ease;
}

.dash-kpi-card:hover {
 box-shadow: var(--now-static-drop-shadow--md);
}

.dash-kpi-card__icon {
 font-size: 1.5rem;
 margin-bottom: var(--snx-space-sm);
}

.dash-kpi-card__value {
 font-size: 2rem;
 font-weight: 700;
 line-height: 1.1;
 margin-bottom: var(--snx-space-xs);
}

.dash-kpi-card__label {
 font-size: 0.75rem;
 font-weight: 600;
 color: var(--snx-color-text-muted);
 text-transform: uppercase;
 letter-spacing: 0.04em;
}

.dash-kpi-card--primary .dash-kpi-card__value {
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}
.dash-kpi-card--info .dash-kpi-card__value {
 color: rgb(var(--now-color_alert--info-2, 0, 106, 168));
}
.dash-kpi-card--positive .dash-kpi-card__value {
 color: rgb(var(--now-color_alert--positive-2, 32, 135, 46));
}
.dash-kpi-card--critical .dash-kpi-card__value {
 color: rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}
.dash-kpi-card--muted .dash-kpi-card__value {
 color: var(--snx-color-text-muted);
}

/* ---- Dashboard Grid ---- */
.cust-dashboard__grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--snx-space-xl);
 margin-bottom: var(--snx-space-xl);
}

/* ---- Dashboard Panel ---- */
.dash-panel {
 padding: var(--snx-space-xl);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.dash-panel__title {
 margin: 0 0 var(--snx-space-lg) 0;
 font-size: var(--now-static-font-size--lg, 1.125rem);
 font-weight: 600;
 color: var(--snx-color-text);
 padding-bottom: var(--snx-space-sm);
 border-bottom: 2px solid var(--snx-color-primary);
}

.dash-panel__empty {
 text-align: center;
 padding: var(--snx-space-xl) 0;
 color: var(--snx-color-text-muted);
 font-size: var(--now-static-font-size--sm, 0.875rem);
 margin: 0;
}

.dash-panel__note {
 margin: var(--snx-space-lg) 0 0 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
 font-style: italic;
}

.dash-panel__good-state {
 display: flex;
 flex-direction: column;
 align-items: center;
 padding: var(--snx-space-xl) 0;
 text-align: center;
}

.dash-panel__good-icon {
 font-size: 2rem;
 margin-bottom: var(--snx-space-sm);
}

.dash-panel__good-text {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: rgb(var(--now-color_alert--positive-2, 32, 135, 46));
 font-weight: 600;
}

/* ---- Order Status Panel ---- */
.dash-status-list {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-md);
}

.dash-status-row {
 display: grid;
 grid-template-columns: auto 1fr auto 100px;
 gap: var(--snx-space-md);
 align-items: center;
}

.dash-status-dot {
 width: 10px;
 height: 10px;
 border-radius: 50%;
 flex-shrink: 0;
}
.dash-status-dot--primary { background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163)); }
.dash-status-dot--info { background-color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); }
.dash-status-dot--positive { background-color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.dash-status-dot--warning { background-color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.dash-status-dot--critical { background-color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }
.dash-status-dot--muted { background-color: var(--snx-color-text-muted); }

.dash-status-label {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text);
}

.dash-status-count {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 font-weight: 700;
 color: var(--snx-color-text);
 text-align: right;
 font-variant-numeric: tabular-nums;
}

.dash-status-bar {
 height: 6px;
 border-radius: 3px;
 background-color: var(--snx-color-surface-alt);
 overflow: hidden;
}

.dash-status-bar__fill {
 height: 100%;
 border-radius: 3px;
 transition: width 300ms ease;
}
.dash-status-bar__fill--primary { background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163)); }
.dash-status-bar__fill--info { background-color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); }
.dash-status-bar__fill--positive { background-color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.dash-status-bar__fill--warning { background-color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.dash-status-bar__fill--critical { background-color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }
.dash-status-bar__fill--muted { background-color: var(--snx-color-text-muted); }

/* ---- Delayed Orders Panel ---- */
.dash-delayed-list {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-sm);
}

.dash-delayed-row {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: var(--snx-space-sm) var(--snx-space-md);
 border-radius: 6px;
 background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.06);
 border-left: 3px solid rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}

.dash-delayed-main {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.dash-delayed-number {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 font-weight: 600;
 color: var(--snx-color-text);
}

.dash-delayed-status {
 font-size: 0.75rem;
 color: var(--snx-color-text-muted);
}

.dash-delayed-meta {
 display: flex;
 flex-direction: column;
 align-items: flex-end;
 gap: 2px;
}

.dash-delayed-date {
 font-size: 0.75rem;
 color: var(--snx-color-text-muted);
}

.dash-delayed-overdue {
 font-size: 0.75rem;
 font-weight: 700;
 color: rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}

/* ---- Demand Chart Placeholder ---- */
.dash-chart-placeholder {
 padding: var(--snx-space-md) 0;
}

.dash-chart-placeholder__bars {
 display: flex;
 align-items: flex-end;
 gap: var(--snx-space-sm);
 height: 120px;
 padding-bottom: var(--snx-space-sm);
 border-bottom: 1px solid var(--snx-color-border);
}

.dash-chart-placeholder__bar {
 flex: 1;
 border-radius: 4px 4px 0 0;
 background: linear-gradient(
 to top,
 rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.2),
 rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.5)
 );
 transition: height 500ms ease;
}

.dash-chart-placeholder__note {
 margin: var(--snx-space-md) 0 0 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
 font-style: italic;
 text-align: center;
}

/* ---- Availability Panel ---- */
.dash-availability-list {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-sm);
}

.dash-availability-row {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: var(--snx-space-sm) 0;
 border-bottom: 1px solid var(--snx-color-border);
}

.dash-availability-row:last-child {
 border-bottom: none;
}

.dash-availability-name {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text);
}

.dash-availability-level {
 font-size: 0.75rem;
 font-weight: 600;
 padding: 2px 10px;
 border-radius: 12px;
}

.dash-availability-level--high {
 background-color: rgba(var(--now-color_alert--positive-2, 32, 135, 46), 0.12);
 color: rgb(var(--now-color_alert--positive-2, 32, 135, 46));
}

.dash-availability-level--medium {
 background-color: rgba(var(--now-color_alert--warning-2, 204, 138, 0), 0.12);
 color: rgb(var(--now-color_alert--warning-2, 204, 138, 0));
}

.dash-availability-level--low {
 background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.12);
 color: rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}

/* ---- Customer Dashboard ---- */
.cust-dashboard {
 max-width: 1100px;
}

.cust-dashboard__welcome {
 margin-bottom: var(--snx-space-xl);
}

.cust-dashboard__title {
 margin: 0 0 var(--snx-space-xs) 0;
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.cust-dashboard__subtitle {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text-muted);
}

/* ---- Dashboard KPI Cards ---- */
.dash-kpi-row {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: var(--snx-space-lg);
 margin-bottom: var(--snx-space-xl);
}

.dash-kpi-card {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: var(--snx-space-xl) var(--snx-space-lg);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 box-shadow: var(--now-static-drop-shadow--sm);
 text-align: center;
 transition: box-shadow 150ms ease;
}

.dash-kpi-card:hover {
 box-shadow: var(--now-static-drop-shadow--md);
}

.dash-kpi-card__icon {
 font-size: 1.5rem;
 margin-bottom: var(--snx-space-sm);
}

.dash-kpi-card__value {
 font-size: 2rem;
 font-weight: 700;
 line-height: 1.1;
 margin-bottom: var(--snx-space-xs);
}

.dash-kpi-card__label {
 font-size: 0.75rem;
 font-weight: 600;
 color: var(--snx-color-text-muted);
 text-transform: uppercase;
 letter-spacing: 0.04em;
}

.dash-kpi-card--primary .dash-kpi-card__value {
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}
.dash-kpi-card--info .dash-kpi-card__value {
 color: rgb(var(--now-color_alert--info-2, 0, 106, 168));
}
.dash-kpi-card--positive .dash-kpi-card__value {
 color: rgb(var(--now-color_alert--positive-2, 32, 135, 46));
}
.dash-kpi-card--critical .dash-kpi-card__value {
 color: rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}
.dash-kpi-card--muted .dash-kpi-card__value {
 color: var(--snx-color-text-muted);
}

/* ---- Dashboard Grid ---- */
.cust-dashboard__grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--snx-space-xl);
 margin-bottom: var(--snx-space-xl);
}

/* ---- Dashboard Panel ---- */
.dash-panel {
 padding: var(--snx-space-xl);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.dash-panel__title {
 margin: 0 0 var(--snx-space-lg) 0;
 font-size: var(--now-static-font-size--lg, 1.125rem);
 font-weight: 600;
 color: var(--snx-color-text);
 padding-bottom: var(--snx-space-sm);
 border-bottom: 2px solid var(--snx-color-primary);
}

.dash-panel__empty {
 text-align: center;
 padding: var(--snx-space-xl) 0;
 color: var(--snx-color-text-muted);
 font-size: var(--now-static-font-size--sm, 0.875rem);
 margin: 0;
}

.dash-panel__note {
 margin: var(--snx-space-lg) 0 0 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
 font-style: italic;
}

.dash-panel__good-state {
 display: flex;
 flex-direction: column;
 align-items: center;
 padding: var(--snx-space-xl) 0;
 text-align: center;
}

.dash-panel__good-icon {
 font-size: 2rem;
 margin-bottom: var(--snx-space-sm);
}

.dash-panel__good-text {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: rgb(var(--now-color_alert--positive-2, 32, 135, 46));
 font-weight: 600;
}

/* ---- Order Status Panel ---- */
.dash-status-list {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-md);
}

.dash-status-row {
 display: grid;
 grid-template-columns: auto 1fr auto 100px;
 gap: var(--snx-space-md);
 align-items: center;
}

.dash-status-dot {
 width: 10px;
 height: 10px;
 border-radius: 50%;
 flex-shrink: 0;
}
.dash-status-dot--primary { background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163)); }
.dash-status-dot--info { background-color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); }
.dash-status-dot--positive { background-color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.dash-status-dot--warning { background-color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.dash-status-dot--critical { background-color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }
.dash-status-dot--muted { background-color: var(--snx-color-text-muted); }

.dash-status-label {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text);
}

.dash-status-count {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 font-weight: 700;
 color: var(--snx-color-text);
 text-align: right;
 font-variant-numeric: tabular-nums;
}

.dash-status-bar {
 height: 6px;
 border-radius: 3px;
 background-color: var(--snx-color-surface-alt);
 overflow: hidden;
}

.dash-status-bar__fill {
 height: 100%;
 border-radius: 3px;
 transition: width 300ms ease;
}
.dash-status-bar__fill--primary { background-color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163)); }
.dash-status-bar__fill--info { background-color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); }
.dash-status-bar__fill--positive { background-color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.dash-status-bar__fill--warning { background-color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.dash-status-bar__fill--critical { background-color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }
.dash-status-bar__fill--muted { background-color: var(--snx-color-text-muted); }

/* ---- Delayed Orders Panel ---- */
.dash-delayed-list {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-sm);
}

.dash-delayed-row {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: var(--snx-space-sm) var(--snx-space-md);
 border-radius: 6px;
 background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.06);
 border-left: 3px solid rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}

.dash-delayed-main {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.dash-delayed-number {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 font-weight: 600;
 color: var(--snx-color-text);
}

.dash-delayed-status {
 font-size: 0.75rem;
 color: var(--snx-color-text-muted);
}

.dash-delayed-meta {
 display: flex;
 flex-direction: column;
 align-items: flex-end;
 gap: 2px;
}

.dash-delayed-date {
 font-size: 0.75rem;
 color: var(--snx-color-text-muted);
}

.dash-delayed-overdue {
 font-size: 0.75rem;
 font-weight: 700;
 color: rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}

/* ---- Demand Chart Placeholder ---- */
.dash-chart-placeholder {
 padding: var(--snx-space-md) 0;
}

.dash-chart-placeholder__bars {
 display: flex;
 align-items: flex-end;
 gap: var(--snx-space-sm);
 height: 120px;
 padding-bottom: var(--snx-space-sm);
 border-bottom: 1px solid var(--snx-color-border);
}

.dash-chart-placeholder__bar {
 flex: 1;
 border-radius: 4px 4px 0 0;
 background: linear-gradient(
 to top,
 rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.2),
 rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.5)
 );
 transition: height 500ms ease;
}

.dash-chart-placeholder__note {
 margin: var(--snx-space-md) 0 0 0;
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
 font-style: italic;
 text-align: center;
}

/* ---- Availability Panel ---- */
.dash-availability-list {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-sm);
}

.dash-availability-row {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: var(--snx-space-sm) 0;
 border-bottom: 1px solid var(--snx-color-border);
}

.dash-availability-row:last-child {
 border-bottom: none;
}

.dash-availability-name {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text);
}

.dash-availability-level {
 font-size: 0.75rem;
 font-weight: 600;
 padding: 2px 10px;
 border-radius: 12px;
}

.dash-availability-level--high {
 background-color: rgba(var(--now-color_alert--positive-2, 32, 135, 46), 0.12);
 color: rgb(var(--now-color_alert--positive-2, 32, 135, 46));
}

.dash-availability-level--medium {
 background-color: rgba(var(--now-color_alert--warning-2, 204, 138, 0), 0.12);
 color: rgb(var(--now-color_alert--warning-2, 204, 138, 0));
}

.dash-availability-level--low {
 background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.12);
 color: rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}

/* ---- Status Badge ---- */
.status-badge {
 display: inline-block;
 padding: 3px 10px;
 font-size: 0.6875rem;
 font-weight: 600;
 border-radius: 12px;
 white-space: nowrap;
 text-transform: capitalize;
}

.status-badge--primary {
 background-color: rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.12);
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}
.status-badge--info {
 background-color: rgba(var(--now-color_alert--info-2, 0, 106, 168), 0.12);
 color: rgb(var(--now-color_alert--info-2, 0, 106, 168));
}
.status-badge--positive {
 background-color: rgba(var(--now-color_alert--positive-2, 32, 135, 46), 0.12);
 color: rgb(var(--now-color_alert--positive-2, 32, 135, 46));
}
.status-badge--warning {
 background-color: rgba(var(--now-color_alert--warning-2, 204, 138, 0), 0.12);
 color: rgb(var(--now-color_alert--warning-2, 204, 138, 0));
}
.status-badge--critical {
 background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.12);
 color: rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}
.status-badge--muted {
 background-color: rgba(var(--now-color_text--secondary, 75, 85, 89), 0.12);
 color: var(--snx-color-text-muted);
}

/* ---- My Orders Section ---- */
.orders-section {
 max-width: 1100px;
}

.orders-header {
 display: flex;
 align-items: baseline;
 justify-content: space-between;
 margin-bottom: var(--snx-space-lg);
}

.orders-header__title {
 margin: 0;
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.orders-header__count {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text-muted);
}

.orders-toolbar {
 display: flex;
 gap: var(--snx-space-lg);
 align-items: flex-end;
 margin-bottom: var(--snx-space-lg);
 flex-wrap: wrap;
}

.orders-toolbar__search {
 flex: 1;
 min-width: 240px;
 max-width: 400px;
}

.orders-toolbar__sort {
 display: flex;
 align-items: center;
}

/* ---- Status Filter Pills ---- */
.orders-status-pills {
 display: flex;
 flex-wrap: wrap;
 gap: var(--snx-space-sm);
 margin-bottom: var(--snx-space-xl);
}

/* ---- Order List ---- */
.orders-list {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-md);
}

.order-row {
 display: grid;
 grid-template-columns: 140px 1fr 120px 100px auto;
 gap: var(--snx-space-md);
 align-items: center;
 padding: var(--snx-space-md) var(--snx-space-lg);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 box-shadow: var(--now-static-drop-shadow--sm);
 transition: box-shadow 150ms ease;
}

.order-row:hover {
 box-shadow: var(--now-static-drop-shadow--md);
}

.order-row__number {
 font-weight: 700;
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 font-size: var(--now-static-font-size--sm, 0.875rem);
}

.order-row__meta {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.order-row__meta-primary {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text);
}

.order-row__meta-secondary {
 font-size: 0.75rem;
 color: var(--snx-color-text-muted);
}

.order-row__qty {
 font-weight: 600;
 font-variant-numeric: tabular-nums;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text);
 text-align: right;
}

/* ---- Order List Header Row ---- */
.orders-list-header {
 display: grid;
 grid-template-columns: 140px 1fr 120px 100px auto;
 gap: var(--snx-space-md);
 padding: var(--snx-space-sm) var(--snx-space-lg);
 font-size: 0.6875rem;
 font-weight: 600;
 color: var(--snx-color-text-muted);
 text-transform: uppercase;
 letter-spacing: 0.04em;
}

/* ---- Order Detail ---- */
.order-detail {
 max-width: 1000px;
}

.order-detail__header {
 margin-bottom: var(--snx-space-xl);
}

.order-detail__title-row {
 display: flex;
 align-items: center;
 gap: var(--snx-space-lg);
 margin: var(--snx-space-md) 0 var(--snx-space-xs) 0;
}

.order-detail__title {
 margin: 0;
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.order-detail__grid {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--snx-space-lg);
 padding: var(--snx-space-xl);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface-alt);
 margin-bottom: var(--snx-space-xl);
}

.order-detail__field {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.order-detail__field--full {
 grid-column: 1 / -1;
}

.order-detail__label {
 font-size: 0.6875rem;
 font-weight: 600;
 color: var(--snx-color-text-muted);
 text-transform: uppercase;
 letter-spacing: 0.04em;
}

.order-detail__value {
 font-size: var(--now-static-font-size--md, 1rem);
 color: var(--snx-color-text);
}

/* ---- Order Items ---- */
.order-items__title {
 margin: 0 0 var(--snx-space-lg) 0;
 font-size: var(--now-static-font-size--lg, 1.125rem);
 font-weight: 600;
 color: var(--snx-color-text);
}

.order-items__list {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-md);
}

.order-item-card {
 padding: var(--snx-space-lg);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.order-item-card__top {
 display: flex;
 justify-content: space-between;
 align-items: flex-start;
 gap: var(--snx-space-lg);
 margin-bottom: var(--snx-space-sm);
}

.order-item-card__product {
 font-weight: 600;
 font-size: var(--now-static-font-size--md, 1rem);
 color: var(--snx-color-text);
}

.order-item-card__details {
 display: flex;
 flex-wrap: wrap;
 gap: var(--snx-space-xl);
 padding-top: var(--snx-space-sm);
 border-top: 1px solid var(--snx-color-border);
}

.order-item-card__detail {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.order-item-card__detail-label {
 font-size: 0.6875rem;
 font-weight: 600;
 color: var(--snx-color-text-muted);
 text-transform: uppercase;
 letter-spacing: 0.04em;
}

.order-item-card__detail-value {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 font-weight: 600;
 color: var(--snx-color-text);
}

.order-item-card__instructions {
 margin-top: var(--snx-space-sm);
 padding-top: var(--snx-space-sm);
 border-top: 1px solid var(--snx-color-border);
}

.order-item-card__instructions-text {
 font-size: var(--now-static-font-size--sm, 0.75rem);
 color: var(--snx-color-text);
 line-height: 1.5;
}

/* ---- Delivery Section ---- */
.del-section {
 max-width: 1100px;
}

.del-section__welcome {
 margin-bottom: var(--snx-space-xl);
}

.del-section__title {
 margin: 0 0 var(--snx-space-xs) 0;
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.del-section__subtitle {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text-muted);
}

.del-section__panels {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-xl);
}

/* ---- Delivery KPI Cards ---- */
.del-kpi-row {
 display: grid;
 grid-template-columns: repeat(4, 1fr);
 gap: var(--snx-space-lg);
 margin-bottom: var(--snx-space-xl);
}

.del-kpi-card {
 display: flex;
 flex-direction: column;
 align-items: center;
 justify-content: center;
 padding: var(--snx-space-xl) var(--snx-space-lg);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 border: 1px solid var(--snx-color-border);
 box-shadow: var(--now-static-drop-shadow--sm);
 text-align: center;
 transition: box-shadow 150ms ease;
}

.del-kpi-card:hover {
 box-shadow: var(--now-static-drop-shadow--md);
}

.del-kpi-card__icon { font-size: 1.5rem; margin-bottom: var(--snx-space-sm); }
.del-kpi-card__value { font-size: 2rem; font-weight: 700; line-height: 1.1; margin-bottom: var(--snx-space-xs); }
.del-kpi-card__label { font-size: 0.75rem; font-weight: 600; color: var(--snx-color-text-muted); text-transform: uppercase; letter-spacing: 0.04em; }

.del-kpi-card--primary .del-kpi-card__value { color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163)); }
.del-kpi-card--warning .del-kpi-card__value { color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.del-kpi-card--critical .del-kpi-card__value { color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }
.del-kpi-card--positive .del-kpi-card__value { color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.del-kpi-card--muted .del-kpi-card__value { color: var(--snx-color-text-muted); }

/* ---- Delivery Tag (On Track / Due Soon / Delayed / Completed) ---- */
.delivery-tag {
 display: inline-block;
 padding: 3px 10px;
 font-size: 0.6875rem;
 font-weight: 600;
 border-radius: 12px;
 white-space: nowrap;
}

.delivery-tag--positive { background-color: rgba(var(--now-color_alert--positive-2, 32, 135, 46), 0.12); color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.delivery-tag--warning { background-color: rgba(var(--now-color_alert--warning-2, 204, 138, 0), 0.12); color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.delivery-tag--critical { background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.12); color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }
.delivery-tag--muted { background-color: rgba(var(--now-color_text--secondary, 75, 85, 89), 0.12); color: var(--snx-color-text-muted); }

/* ---- Delivery Panel ---- */
.del-panel {
 padding: var(--snx-space-xl);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.del-panel--alert {
 border-left: 4px solid rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}

.del-panel__title {
 margin: 0 0 var(--snx-space-lg) 0;
 font-size: var(--now-static-font-size--lg, 1.125rem);
 font-weight: 600;
 color: var(--snx-color-text);
 padding-bottom: var(--snx-space-sm);
 border-bottom: 1px solid var(--snx-color-border);
}

.del-panel__empty { text-align: center; padding: var(--snx-space-xl) 0; }
.del-panel__empty-text { margin: 0; color: var(--snx-color-text-muted); font-size: var(--now-static-font-size--sm, 0.875rem); }

.del-panel__good { display: flex; flex-direction: column; align-items: center; padding: var(--snx-space-xl) 0; text-align: center; }
.del-panel__good-icon { font-size: 2rem; margin-bottom: var(--snx-space-sm); }
.del-panel__good-text { margin: 0; font-size: var(--now-static-font-size--sm, 0.875rem); color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); font-weight: 600; }

/* ---- Delivery Row ---- */
.del-list { display: flex; flex-direction: column; gap: var(--snx-space-md); }

.del-row {
 display: grid;
 grid-template-columns: 1fr auto auto auto;
 gap: var(--snx-space-lg);
 align-items: center;
 padding: var(--snx-space-md) var(--snx-space-lg);
 border-radius: 6px;
 background-color: var(--snx-color-surface-alt);
 border: 1px solid var(--snx-color-border);
 transition: box-shadow 150ms ease;
}

.del-row:hover { box-shadow: var(--now-static-drop-shadow--sm); }

.del-row--overdue {
 background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.04);
 border-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.3);
}

.del-row__main { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.del-row__number { font-weight: 700; color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163)); font-size: var(--now-static-font-size--sm, 0.875rem); }
.del-row__meta { display: flex; flex-direction: column; gap: 2px; }
.del-row__date { font-size: 0.75rem; color: var(--snx-color-text-muted); }
.del-row__days { margin-left: var(--snx-space-xs); font-weight: 600; }
.del-row__location { font-size: 0.75rem; color: var(--snx-color-text-muted); }

.del-row__status-area { display: flex; flex-direction: column; gap: var(--snx-space-xs); align-items: flex-end; }

.del-row__info { display: flex; flex-direction: column; gap: 2px; align-items: flex-end; }
.del-row__priority { font-size: 0.75rem; color: var(--snx-color-text-muted); font-weight: 600; }
.del-row__qty { font-size: 0.75rem; color: var(--snx-color-text); font-weight: 600; font-variant-numeric: tabular-nums; }

.del-row__overdue-badge { display: flex; flex-direction: column; align-items: center; padding: var(--snx-space-xs) var(--snx-space-md); background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.1); border-radius: 6px; }
.del-row__overdue-days { font-size: 1.5rem; font-weight: 700; color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); line-height: 1; }
.del-row__overdue-label { font-size: 0.625rem; font-weight: 600; color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); text-transform: uppercase; letter-spacing: 0.04em; }

.del-row__action { display: flex; }

/* ---- Demand Section ---- */
.demand-section { max-width: 1100px; }
.demand-section__welcome { margin-bottom: var(--snx-space-xl); }
.demand-section__title { margin: 0 0 var(--snx-space-xs) 0; font-size: var(--now-static-font-size--xl, 1.5rem); font-weight: 700; color: var(--snx-color-text); }
.demand-section__subtitle { margin: 0; font-size: var(--now-static-font-size--sm, 0.875rem); color: var(--snx-color-text-muted); }

/* ---- Demand Trend Panel ---- */
.demand-panel { padding: var(--snx-space-xl); border: 1px solid var(--snx-color-border); border-radius: var(--snx-radius-card); background-color: var(--snx-color-surface); box-shadow: var(--now-static-drop-shadow--sm); margin-bottom: var(--snx-space-xl); }
.demand-panel__header { display: flex; justify-content: space-between; align-items: center; margin-bottom: var(--snx-space-lg); flex-wrap: wrap; gap: var(--snx-space-md); }
.demand-panel__title { margin: 0; font-size: var(--now-static-font-size--lg, 1.125rem); font-weight: 600; color: var(--snx-color-text); }
.demand-panel__period-selector { display: flex; gap: var(--snx-space-sm); }
.demand-panel__loading { text-align: center; padding: var(--snx-space-xl) 0; color: var(--snx-color-text-muted); margin: 0; }
.demand-panel__empty { text-align: center; }
.demand-panel__empty-note { margin: var(--snx-space-lg) 0 var(--snx-space-sm) 0; font-size: var(--now-static-font-size--sm, 0.875rem); color: var(--snx-color-text-muted); font-style: italic; }
.demand-panel__api-hint { margin: 0; font-size: 0.75rem; color: var(--snx-color-text-muted); }
.demand-panel__api-hint code { background-color: var(--snx-color-surface-alt); padding: 2px 6px; border-radius: 4px; font-size: 0.6875rem; }
.demand-panel__legend { display: flex; justify-content: center; gap: var(--snx-space-lg); padding: var(--snx-space-md) 0; }
.demand-legend-item { font-size: 0.75rem; font-weight: 600; }
.demand-legend-item--up { color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.demand-legend-item--stable { color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); }
.demand-legend-item--down { color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }

/* Demand chart placeholder bars */
.demand-chart-bars { display: flex; align-items: flex-end; gap: var(--snx-space-xs); height: 140px; padding: var(--snx-space-md) 0; border-bottom: 1px solid var(--snx-color-border); }
.demand-chart-bar { flex: 1; border-radius: 4px 4px 0 0; background: linear-gradient(to top, rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.15), rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.4)); transition: height 500ms ease; }

/* Demand product results */
.demand-panel__results { display: flex; flex-direction: column; gap: var(--snx-space-sm); }
.demand-product-row { display: flex; align-items: center; gap: var(--snx-space-lg); padding: var(--snx-space-sm) 0; border-bottom: 1px solid var(--snx-color-border); }
.demand-product-row:last-child { border-bottom: none; }
.demand-product-row__name { flex: 1; font-size: var(--now-static-font-size--sm, 0.875rem); color: var(--snx-color-text); font-weight: 600; }
.demand-product-row__change { font-size: 0.75rem; font-weight: 600; font-variant-numeric: tabular-nums; }

/* Trend indicators */
.demand-trend-indicator { font-size: 0.75rem; font-weight: 600; padding: 2px 8px; border-radius: 10px; text-transform: capitalize; }
.demand-trend-indicator--increasing { background-color: rgba(var(--now-color_alert--positive-2, 32, 135, 46), 0.12); color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.demand-trend-indicator--stable { background-color: rgba(var(--now-color_alert--info-2, 0, 106, 168), 0.12); color: rgb(var(--now-color_alert--info-2, 0, 106, 168)); }
.demand-trend-indicator--decreasing { background-color: rgba(var(--now-color_alert--warning-2, 204, 138, 0), 0.12); color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.demand-trend-indicator--unknown { background-color: rgba(var(--now-color_text--secondary, 75, 85, 89), 0.12); color: var(--snx-color-text-muted); }

/* ---- Availability Panel ---- */
.avail-panel { padding: var(--snx-space-xl); border: 1px solid var(--snx-color-border); border-radius: var(--snx-radius-card); background-color: var(--snx-color-surface); box-shadow: var(--now-static-drop-shadow--sm); }
.avail-panel__title { margin: 0 0 var(--snx-space-lg) 0; font-size: var(--now-static-font-size--lg, 1.125rem); font-weight: 600; color: var(--snx-color-text); }

.avail-summary-row { display: flex; gap: var(--snx-space-lg); margin-bottom: var(--snx-space-lg); }
.avail-summary-card { flex: 1; display: flex; flex-direction: column; align-items: center; padding: var(--snx-space-md); border-radius: var(--snx-radius-card); border: 1px solid var(--snx-color-border); }
.avail-summary-card__value { font-size: 1.5rem; font-weight: 700; line-height: 1.1; }
.avail-summary-card__label { font-size: 0.6875rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; color: var(--snx-color-text-muted); }
.avail-summary-card--available .avail-summary-card__value { color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.avail-summary-card--limited .avail-summary-card__value { color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.avail-summary-card--unavailable .avail-summary-card__value { color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }

.avail-toolbar { display: flex; gap: var(--snx-space-lg); margin-bottom: var(--snx-space-lg); align-items: flex-end; flex-wrap: wrap; }
.avail-toolbar__search { flex: 1; min-width: 200px; max-width: 360px; }
.avail-toolbar__pills { display: flex; flex-wrap: wrap; gap: var(--snx-space-sm); }

.avail-list { display: flex; flex-direction: column; gap: var(--snx-space-sm); }
.avail-row { display: grid; grid-template-columns: 1fr auto auto; gap: var(--snx-space-lg); align-items: center; padding: var(--snx-space-sm) var(--snx-space-md); border-bottom: 1px solid var(--snx-color-border); }
.avail-row:last-child { border-bottom: none; }
.avail-row__info { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.avail-row__name { font-size: var(--now-static-font-size--sm, 0.875rem); font-weight: 600; color: var(--snx-color-text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.avail-row__meta { font-size: 0.75rem; color: var(--snx-color-text-muted); }
.avail-row__stock { text-align: right; }
.avail-row__qty { font-size: var(--now-static-font-size--sm, 0.875rem); font-weight: 600; color: var(--snx-color-text); font-variant-numeric: tabular-nums; }

.avail-badge { display: inline-block; padding: 3px 10px; font-size: 0.6875rem; font-weight: 600; border-radius: 12px; white-space: nowrap; }
.avail-badge--available { background-color: rgba(var(--now-color_alert--positive-2, 32, 135, 46), 0.12); color: rgb(var(--now-color_alert--positive-2, 32, 135, 46)); }
.avail-badge--limited { background-color: rgba(var(--now-color_alert--warning-2, 204, 138, 0), 0.12); color: rgb(var(--now-color_alert--warning-2, 204, 138, 0)); }
.avail-badge--unavailable { background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.12); color: rgb(var(--now-color_alert--critical-2, 200, 30, 53)); }

/* ---- Customer Profile Section ---- */
.profile-section { max-width: 900px; }

.profile-section__header {
 display: flex;
 justify-content: space-between;
 align-items: center;
 padding: var(--snx-space-xl);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background: linear-gradient(135deg, rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.08), rgba(var(--now-actionable--primary--background-color, 0, 128, 163), 0.02));
 margin-bottom: var(--snx-space-xl);
}

.profile-section__header-info {
 display: flex;
 align-items: center;
 gap: var(--snx-space-lg);
}

.profile-section__avatar {
 font-size: 2.5rem;
 width: 56px;
 height: 56px;
 display: flex;
 align-items: center;
 justify-content: center;
 border-radius: 50%;
 background-color: var(--snx-color-surface-alt);
 border: 2px solid var(--snx-color-border);
 flex-shrink: 0;
}

.profile-section__name {
 margin: 0 0 2px 0;
 font-size: var(--now-static-font-size--xl, 1.5rem);
 font-weight: 700;
 color: var(--snx-color-text);
}

.profile-section__id {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text-muted);
}

.profile-active-badge {
 display: inline-block;
 padding: 4px 14px;
 font-size: 0.75rem;
 font-weight: 600;
 border-radius: 12px;
 white-space: nowrap;
}

.profile-active-badge--yes {
 background-color: rgba(var(--now-color_alert--positive-2, 32, 135, 46), 0.12);
 color: rgb(var(--now-color_alert--positive-2, 32, 135, 46));
}

.profile-active-badge--no {
 background-color: rgba(var(--now-color_alert--critical-2, 200, 30, 53), 0.12);
 color: rgb(var(--now-color_alert--critical-2, 200, 30, 53));
}

/* Profile Cards Grid */
.profile-cards {
 display: grid;
 grid-template-columns: 1fr 1fr;
 gap: var(--snx-space-xl);
}

.profile-card {
 padding: var(--snx-space-xl);
 border: 1px solid var(--snx-color-border);
 border-radius: var(--snx-radius-card);
 background-color: var(--snx-color-surface);
 box-shadow: var(--now-static-drop-shadow--sm);
}

.profile-card--full {
 grid-column: 1 / -1;
}

.profile-card__title {
 margin: 0 0 var(--snx-space-lg) 0;
 font-size: var(--now-static-font-size--md, 1rem);
 font-weight: 600;
 color: var(--snx-color-text);
 padding-bottom: var(--snx-space-sm);
 border-bottom: 2px solid var(--snx-color-primary);
}

.profile-card__fields {
 display: flex;
 flex-direction: column;
 gap: var(--snx-space-md);
}

.profile-card__notes {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text);
 line-height: 1.6;
}

/* Profile Field */
.profile-field {
 display: flex;
 flex-direction: column;
 gap: 2px;
}

.profile-field__label {
 font-size: 0.6875rem;
 font-weight: 600;
 color: var(--snx-color-text-muted);
 text-transform: uppercase;
 letter-spacing: 0.04em;
}

.profile-field__value {
 font-size: var(--now-static-font-size--sm, 0.875rem);
 color: var(--snx-color-text);
 font-weight: 500;
}

/* ---- Responsive Portal ---- */
@media (max-width: 900px) {
 .portal-sidebar {
 width: 56px;
 min-width: 56px;
 padding: var(--snx-space-sm) 0;
 }
 .portal-sidebar__label {
 display: none;
 }
 .portal-sidebar__item {
 justify-content: center;
 padding: 10px;
 }
 .portal-sidebar__icon {
 width: auto;
 }
 .storefront-grid {
 grid-template-columns: 1fr;
 }
 .portal-header__tagline {
 display: none;
 }
 .dash-kpi-row {
 grid-template-columns: repeat(2, 1fr);
 }
 .cust-dashboard__grid {
 grid-template-columns: 1fr;
 }
 .order-row {
 grid-template-columns: 1fr;
 gap: var(--snx-space-sm);
 }
 .orders-list-header {
 display: none;
 }
 .order-detail__grid {
 grid-template-columns: 1fr;
 }
 .del-kpi-row {
 grid-template-columns: repeat(2, 1fr);
 }
 .del-row {
 grid-template-columns: 1fr;
 gap: var(--snx-space-sm);
 }
 .avail-summary-row { flex-direction: column; }
 .avail-row { grid-template-columns: 1fr; gap: var(--snx-space-sm); }
 .demand-panel__header { flex-direction: column; align-items: flex-start; }
 .profile-cards { grid-template-columns: 1fr; }
 .profile-section__header { flex-direction: column; gap: var(--snx-space-md); align-items: flex-start; }
}

@media (max-width: 600px) {
 .portal-content {
 padding: var(--snx-space-md);
 }
 .storefront-hero {
 padding: var(--snx-space-lg) var(--snx-space-md);
 }
 .storefront-hero__title {
 font-size: 1.35rem;
 }
 .storefront-card__actions {
 flex-direction: column;
 }
 .dash-kpi-row {
 grid-template-columns: 1fr;
 }
 .del-kpi-row {
 grid-template-columns: 1fr;
 }
 .dash-status-row {
 grid-template-columns: auto 1fr auto;
 }
 .dash-status-bar {
 display: none;
 }
 .orders-toolbar {
 flex-direction: column;
 }
 .order-item-card__details {
 flex-direction: column;
 gap: var(--snx-space-md);
 }
 .avail-toolbar { flex-direction: column; }
}
